mapper.select:
SELECT id, subscription_id, generation, kind, user_id, store_id, shop_id, goods_id, title, content, delivery_state, request_id,
    target_client_id, attempts, version, next_attempt_at, expires_at, created_at, updated_at, read_at, clicked_at,
    last_error FROM dodo_restock_notice


    LIMIT #{limit}
    OFFSET #{start}

mapper.update:
UPDATE dodo_restock_notice
SET delivery_state = #{deliveryState}, target_client_id = #{targetClientId,jdbcType=VARCHAR}, attempts = #{attempts},
    version = #{version}, next_attempt_at = #{nextAttemptAt}, updated_at = #{updatedAt}, last_error = #{lastError,jdbcType=VARCHAR}
WHERE id = #{id} AND user_id = #{userId} AND store_id = #{storeId} AND shop_id = #{shopId}

mapper.select:
SELECT * FROM dodo_restock_notice WHERE id = #{id}
AND store_id = #{storeId}
FOR UPDATE

mapper.update:
UPDATE dodo_restock_notice SET read_at = COALESCE(read_at, #{readAt}),
clicked_at = CASE WHEN #{clicked} THEN COALESCE(clicked_at, #{readAt}) ELSE clicked_at END
WHERE id = #{id} AND user_id = #{userId} AND store_id = #{storeId} AND shop_id = #{shopId}

mapper.select:
SELECT id FROM dodo_restock_notice WHERE delivery_state = 'PENDING' AND next_attempt_at <= CURRENT_TIMESTAMP(3)
AND store_id = #{storeId}
ORDER BY next_attempt_at, id LIMIT #{limit}

mapper.update:
UPDATE dodo_restock_notice SET delivery_state = #{state}, version = version + 1,
updated_at = #{updatedAt}, last_error = #{error,jdbcType=VARCHAR}
WHERE id = #{id} AND delivery_state = 'SENDING' AND attempts = #{attempts}

UPDATE dodo_restock_notice SET delivery_state = 'UNKNOWN', version = version + 1,
last_error = 'WORKER_INTERRUPTED', updated_at = #{updatedAt}
WHERE delivery_state = 'SENDING' AND updated_at < #{interruptedBefore}

UPDATE dodo_restock_notice SET delivery_state = #{outcome}, version = version + 1,
last_error = 'MANUALLY_RECONCILED', updated_at = #{updatedAt}
WHERE id = #{id} AND store_id = #{storeId} AND version = #{version} AND delivery_state = 'UNKNOWN'
